package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaTeDraft3 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_seeing_first_fruit" to DuaText("మొదటి పండును చూడటం", "ఓ అల్లాహ్, మా పండ్లలో మమ్మల్ని ఆశీర్వదించండి, మా నగరంలో మమ్మల్ని ఆశీర్వదించండి, మా సా'మరియు మా మడ్లో (కొలతలు) మమ్మల్ని ఆశీర్వదించండి.", "సీజన్ యొక్క మొదటి పండు చూసినప్పుడు.", "ఒకరి నగరంలో మరియు ఒకరి వసతిలో ఆశీర్వాదం కోసం ఒక దుఆ."),
        "dua_good_news" to DuaText("సంతోషకరమైన వార్తలు", "అన్ని ప్రశంసలు అల్లాహ్కు, ఆయన అనుగ్రహం ద్వారా మంచి పనులు పూర్తవుతాయి.", "శుభవార్త అందినప్పుడు (కృతజ్ఞతతో సాష్టాంగ నమస్కారం చేయండి).", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం తనకు నచ్చినదాన్ని చూసినప్పుడు ఈ విషయం చెప్పారు."),
        "dua_looking_mirror" to DuaText("అద్దంలో చూస్తూ", "ఓ అల్లాహ్, నీవు నా రూపాన్ని ఎలా బాగు చేశావో, అలాగే నా పాత్రను కూడా బాగు చేస్కొనుము.", "అద్దంలో చూస్తున్నప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆ (ఇది అద్దం ప్రస్తావన లేకుండా కూడా స్థాపించబడింది) చేశారు."),
        "dua_rabbana_taqabbal" to DuaText("చర్యలను అంగీకరించడం", "మా ప్రభూ, మా నుండి దీనిని అంగీకరించండి. నిశ్చయంగా నీవు అన్నీ వినేవాడవు, అన్నీ తెలిసినవాడవు. మరియు మా పశ్చాత్తాపాన్ని అంగీకరించండి. నిశ్చయంగా నీవు పశ్చాత్తాపానికి మార్గదర్శి, దయగలవాడవు.", "కాబా నిర్మిస్తున్నప్పుడు ఇబ్రహీం మరియు ఇస్మాయిల్ (AS) అడిగారు.", "ప్రతి మంచి పని తర్వాత ఆమోదానికి ఒక దుఆ."),
        "dua_muawwidhat" to DuaText("మూడు కుల్లు (ము'ఆవ్ విధత్)", "(సూరహ్ అల్-ఇఖ్లాస్) ఇలా చెప్పండిః ఆయనే అల్లాహ్, ఒక్కడే. అల్లాహ్, స్వయం సమృద్ధిగలవాడు. ఆయనేమీ జన్మించడు, జన్మించడు. ఆయనతో పోల్చదగినవాడు లేడు.\n\n(సూరహ్ అల్-తలాక్) ఇలా చెప్పండిః నేను ఉదయపు ప్రభువు వద్ద, ఆయన సృష్టించిన వాటి చెడు నుండి, అది స్థిరపడినప్పుడు చీకటి చెడు నుండి, గడ్డలు పేల్చే వారి చెడు నుండి, మరియు అసూయపడేవారి చెడు నుండి ఆశ్రయం పొందుతున్నాను.\n\n(సూరహ్-నాస్) ఇలా చెప్పండిః నేను మానవజాతి యొక్క ప్రభువు, మానవజాతి యొక్క రాజు, మానవజాతి యొక్క దేవుని వద్ద ఆశ్రయం కోరుతున్నాను, వెనుకకు తిరిగే గుసగుసలాడే దుష్టత్వం నుండి, అతను జిన్నుల నుండి మరియు మానవజాతి నుండి మానవజాతి హృదయాలలో గుసగుసలాడుతాడు.", "మూడు సూరాలు ప్రతిరోజూ ఉదయం మరియు సాయంత్రం మూడు సార్లు, మరియు నిద్రపోయే ముందు, చేతుల్లోకి ఊపుతారు మరియు శరీరంపై తుడిచివేస్తారు.", "ఉదయం, సాయంత్రం మూడు సార్లు వాటిని పఠిస్తే సరిపోతుంది."),
        "dua_sabr" to DuaText("సహనం మరియు స్థిరత్వం కోసం", "మా ప్రభూ, మాపై సహనాన్ని నింపండి, మా పాదాలను దృఢపరచండి మరియు అవిశ్వాసుల నుండి మాకు సహాయం చేయండి.", "కష్టాలు మరియు ఘర్షణ సమయాల్లో.", "తలుత్ సైన్యం యొక్క దుఆ."),
        "dua_rabbana_innana_amanna" to DuaText("క్షమాపణ మరియు అగ్ని నుండి రక్షణ", "మా ప్రభూ, మేము విశ్వసించాము, కాబట్టి మా పాపాలను క్షమించండి మరియు అగ్ని శిక్ష నుండి మమ్మల్ని రక్షించండి.", "ఖురాన్ దుఆ.", "దేవునికి భయపడేవారి లక్షణాలలో ఒక దుఆ ప్రస్తావించబడింది."),
        "dua_rabbana_hab_lana_rahmah" to DuaText("మా వ్యవహారంలో మార్గదర్శకత్వం (అషాబ్ అల్-కహ్ఫ్)", "మా ప్రభూ, మీ నుండి మాకు దయ చూపండి మరియు మా వ్యవహారంలో మాకు సరైన మార్గదర్శకత్వాన్ని సిద్ధం చేయండి.", "గుహ యొక్క ప్రజల దుఆ.", "నిర్ణయాలు మరియు క్లిష్ట పరిస్థితులలో మార్గదర్శకత్వం."),
        "dua_musa_faqir" to DuaText("ఏర్పాటు కోసం మూసా (ఏఎస్) యొక్క దువా", "నా ప్రభూ, నీవు నాకు పంపే ఏ మంచి అయినా నాకు నిజంగా అవసరం.", "ఏర్పాటు మరియు మంచిని కోరుతూ-మాద్యాన్లో మూసా (ఏఎస్) యొక్క దుఆ.", "ఈ దుఆ తరువాత, అల్లాహ్ మూసాకు ఇల్లు, పని మరియు భార్యను మంజూరు చేశాడు."),
        "dua_ayyub" to DuaText("అనారోగ్యంతో ఉన్న అయ్యూబ్ (ఏఎస్) దువా", "(నా ప్రభూ,) హాని నన్ను తాకింది, మరియు నీవు కరుణామయుడులో అత్యంత దయగలవాడవు.", "అనారోగ్యం మరియు బాధలో.", "అల్లాహ్ అయ్యూబ్ (అ. స.) బాధను తొలగించాడు."),
        "dua_husn_khatimah" to DuaText("ముస్లింగా చనిపోవండి (యూసుఫ్ AS)", "ఆకాశాలను, భూమిని సృష్టించిన నీవే ఈ లోకంలో, పరలోకంలో నాకు రక్షకుడవు. నన్ను ముస్లింగా మరణింపజేయండి, నీతిమంతులతో నాతో చేరండి.", "మంచి ముగింపు కోసం ఒక దుఆ.", "ప్రవక్త యూసుఫ్ (అ. స.) యొక్క దుఆ."),
        "dua_shaitan_hamazat" to DuaText("దెయ్యాల విస్పర్స్ నుండి ఆశ్రయం", "నా ప్రభూ, నేను దయ్యాల గుసగుసల నుండి నిన్ను ఆశ్రయిస్తున్నాను, మరియు వారు నా దగ్గరకు రాకపోతే నేను నిన్ను ఆశ్రయిస్తున్నాను, నా ప్రభూ.", "సాతాను గుసగుసల నుండి ఆశ్రయం పొందండి.", "ఆశ్రయం కోరుతూ ఖురాన్ యొక్క దుఆ."),
        "dua_bad_character" to DuaText("చెడు స్వభావం నుండి ఆశ్రయం", "ఓ అల్లాహ్, నేను చెడు స్వభావం, చెడు పనులు మరియు చెడు కోరికల నుండి నిన్ను ఆశ్రయిస్తున్నాను.", "చెడు స్వభావం, పనులు మరియు కోరికల నుండి ఆశ్రయం పొందండి.", "ప్రవక్త నుండి ఆశ్రయం యొక్క దుఆ."),
        "dua_zawal_nimah" to DuaText("ఆశీర్వాదాల నష్టం నుండి శరణార్థి", "ఓ అల్లాహ్, నీ ఆశీర్వాదాల నష్టం నుండి, నీవు ఇచ్చిన శ్రేయస్సు మార్పు నుండి, నీ ఆకస్మిక శిక్ష నుండి మరియు నీ అన్ని అసంతృప్తుల నుండి నేను నీకు ఆశ్రయం కోరుతున్నాను.", "ఆశీర్వాదాలను కోల్పోవడం నుండి మరియు ఆకస్మిక విపత్తు నుండి శరణార్థిగా ఉండండి.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క ఒక దుఆ."),
        "dua_useless_knowledge" to DuaText("ప్రయోజనకరం కాని జ్ఞానం నుండి శరణాగతి", "ఓ అల్లాహ్, ప్రయోజనం లేని జ్ఞానం నుండి, భయం లేని హృదయం నుండి, ఎన్నటికీ సంతృప్తి చెందని ఆత్మ నుండి మరియు సమాధానం లేని దుఆ నుండి నేను నీలో ఆశ్రయం కోరుతున్నాను.", "పనికిరాని జ్ఞానం నుండి మరియు అల్లాహ్ పట్ల భయం లేని హృదయం నుండి శరణాగతి పొందండి.", "ప్రవక్త నుండి ఆశ్రయం యొక్క దుఆ."),
        "dua_beneficial_knowledge" to DuaText("ప్రయోజనకరమైన జ్ఞానం & హలాల్ రిజక్", "ఓ అల్లాహ్, నేను ప్రయోజనకరమైన జ్ఞానం, స్వచ్ఛమైన ఆహారం మరియు ఆమోదించబడిన పనులు కోసం నిన్ను అడుగుతున్నాను.", "ఫజ్ ప్రార్థన తరువాత.", "ఫజ్ ర్ సలాం తరువాత ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ విషయం చెప్పారు."),
        "dua_leprosy_diseases" to DuaText("తీవ్రమైన వ్యాధుల నుండి శరణార్థులు", "ఓ అల్లాహ్, నేను కోడిపిల్ల, పిచ్చి, కుష్టు వ్యాధి మరియు అన్ని దుష్ట వ్యాధుల నుండి నిన్ను ఆశ్రయిస్తున్నాను.", "తీవ్రమైన వ్యాధుల నుండి రక్షణ.", "ఆరోగ్యాన్ని కాపాడటానికి సున్నహ్ దుఆ."),
        "dua_fear_people" to DuaText("శత్రువులు లేదా అణచివేతదారుల భయం", "ఓ అల్లాహ్, మేము నిన్ను వారి ముందు ఉంచుతాము మరియు వారి చెడు నుండి నీకు ఆశ్రయం కోరుతున్నాము.", "ఒక ప్రజలు లేదా ఒక వ్యక్తి యొక్క హానిని భయపడినప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఒక ప్రజలకు భయపడినప్పుడు ఈ విషయం చెప్పారు."),
        "dua_shirk_protection" to DuaText("హిడెన్ షిర్క్ నుండి రక్షణ", "ఓ అల్లాహ్, నేను తెలిసి మీతో ఏదైనా అనుబంధించకుండా మీలో ఆశ్రయం కోరుతున్నాను, మరియు నేను తెలియకుండానే చేసిన పనికి మీ క్షమాపణ కోరుతున్నాను.", "చూపించడం మరియు దాచిన షిర్క్ నుండి సురక్షితంగా ఉండటానికి.", "చీమల ఊగటం కంటే దాచిన షిర్క్ మరింత దాచబడుతుంది."),
        "dua_rain" to DuaText("వర్షం పడినప్పుడు", "ఓ అల్లాహ్, (పంపండి) ప్రయోజనకరమైన వర్షం.", "వర్షం పడుతున్నప్పుడు.", "వర్షం అనేది దుఆలు ఆమోదించబడే సమయం."),
        "dua_after_rain" to DuaText("వర్షం తరువాత", "అల్లాహ్ యొక్క అనుగ్రహం మరియు అతని దయ ద్వారా మాకు వర్షం కురిసింది.", "వర్షం తరువాత.", "ఇలా చెప్పేవాడు అల్లాహ్ ను విశ్వసించేవాడు."),
        "dua_istisqa" to DuaText("వర్షం కోసం అడగడం (ఇస్తిస్కా)", "ఓ అల్లాహ్, మాకు వర్షం (మూడు సార్లు) పంపండి.", "వర్షం లేనప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం శుక్రవారం ఉపన్యాసంలో ఈ దుఆ చేశారు మరియు వర్షం కురిసింది."),
        "dua_heavy_rain" to DuaText("అతిగా వర్షాలు", "ఓ అల్లాహ్, (అది మన చుట్టూ పడనివ్వండి), మనపై కాదు.", "చాలా ఎక్కువ వర్షం పడినప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం యొక్క దుఆ ద్వారా మేఘాలు దూరంగా కదిలాయి."),
        "dua_wind" to DuaText("గాలి వీచినప్పుడు", "ఓ అల్లాహ్, దాని మంచిని, దానిలోని మంచిని, దానితో పంపబడిన మంచిని నేను నిన్ను అడుగుతున్నాను, మరియు దాని చెడు నుండి, దానిలోని చెడు నుండి, దానితో పంపబడిన చెడు నుండి నేను నిన్ను ఆశ్రయిస్తున్నాను.", "బలమైన గాలి లేదా తుఫాను వీచినప్పుడు.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం తుఫానుల సమయంలో ఈ దుఆ చేశారు."),
        "dua_thunder" to DuaText("వినికిడి ఉరుము", "ఉరుములు తన స్తుతితో మహిమపరుచుకునేవారికి, మరియు ఆయనకు భయపడి ఉన్న దేవతలకు మహిమ కలగాలి.", "ఉరుములు విన్నప్పుడు-అబ్దుల్లా ఇబ్న్ అజ్-జుబైర్ (రా) యొక్క ఆచారం.", "సూరహ్ అర్-రాద్ (13:13) నుండి తీసుకోబడింది."),
        "dua_new_moon" to DuaText("అమావాస్యను చూడటం", "ఓ అల్లాహ్, ఈ చంద్రుడు ఆశీర్వాదం, విశ్వాసం, భద్రత మరియు ఇస్లాం తో మనపై ఉదయించనివ్వండి. (చంద్రుడా,) నా ప్రభువు మరియు నీ ప్రభువు అల్లాహ్.", "అమావాస్యను చూసినప్పుడు.", "ప్రతి కొత్త నెల సున్నహ్ దుఆ."),
        "dua_janaza_adult" to DuaText("జనాజా ప్రార్థన (వయోజనులు)", "ఓ అల్లాహ్, మా సజీవులను, మా మృతులను, అక్కడ ఉన్నవారిని, మా యువకులను, మా వృద్ధులను, మా పురుషులను, మా స్త్రీలను క్షమించు. ఓ అల్లాహ్, మాలో ఎవరినైనా నీవు సజీవంగా ఉంచితే, ఇస్లాం మీద అతన్ని సజీవంగా ఉంచు, మరియు మాలో ఎవరినైనా నీవు మరణింపజేస్తే, విశ్వాసంతో అతన్ని మరణింపజేయుము.", "అంత్యక్రియల ప్రార్థన యొక్క మూడవ తక్బీర్ తరువాత.", "మరణించిన వయోజనులకు సున్నహ్ దుఆ."),
        "dua_janaza_child" to DuaText("జనాజా ప్రార్థన (బాల)", "ఓ అల్లాహ్, అతన్ని మాకు పూర్వగామిగా (మరియు ఆతిథ్యమిచ్చే) చేయండి, అతన్ని మాకు బహుమతిగా మరియు నిధిగా చేయండి, మరియు అతని మధ్యవర్తిత్వం ఆమోదించబడిన మాకు మధ్యవర్తిగా చేయండి.", "పిల్లల అంత్యక్రియల ప్రార్థనలో (ఒక అమ్మాయికి'ఇజల్హా'అని చెప్పండి).", "హనాఫీలు సున్నహ్ దుఆను అభ్యసించారు."),
        "dua_mayyit_awf" to DuaText("మృతుల కోసం వివరణాత్మక దువా", "ఓ అల్లాహ్, అతన్ని క్షమించు, అతనిపై దయ చూపించు, అతనికి శ్రేయస్సు ఇవ్వు, అతనికి క్షమాపణ ఇవ్వు. అతని స్వాగతాన్ని గౌరవప్రదంగా మరియు అతని సమాధిని విశాలంగా చేయండి, నీరు, మంచు మరియు వడగళ్ళతో కడిగి, తెల్లటి వస్త్రం మురికి నుండి శుద్ధి చేయబడినట్లుగా పాపాల నుండి అతనిని శుభ్రపరుచుకో.", "అంత్యక్రియల ప్రార్థనలో లేదా మరణించిన వారి కోసం.", "అవ్ఫ్ ఇబ్న్ మాలిక్ (ర) తాను ఆ మరణించిన వ్యక్తిగా ఉండాలని కోరుకున్నాడు."),
        "dua_visiting_graves" to DuaText("సమాధులను సందర్శించడం", "ఈ గృహాల్లో నివసించే విశ్వాసులారా, ముస్లింలారా, మీకు శాంతి కలుగుగాక. అల్లాహ్ కోరుకుంటే మేము కూడా మీతో చేరతాము. మాకు, మీకు శ్రేయస్సు చేకూరాలని నేను అల్లాహ్ను కోరుతున్నాను.", "స్మశానవాటికలోకి ప్రవేశించినప్పుడు.", "సమాధులను సందర్శించడం అనేది మరణాన్ని, పరలోకాన్ని గుర్తు చేస్తుంది."),
        "dua_closing_eyes" to DuaText("మృతుల కళ్ళు మూసుకున్నప్పుడు", "ఓ అల్లాహ్, క్షమించు (పేరు), మార్గనిర్దేశం పొందిన వారిలో అతని హోదాను పెంచు, అతను విడిచిపెట్టిన వారిలో అతని వారసుడిగా ఉండు. లోకాల ప్రభువు, మమ్మల్ని మరియు అతన్ని క్షమించండి, అతని సమాధిని విశాలంగా చేసి, దానిని కాంతితో నింపండి.", "మరణించిన వ్యక్తి కళ్ళు మూసుకున్నప్పుడు (అతని పేరు ప్రస్తావిస్తూ).", "అబూ సలమా (ర) కోసం ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ దుఆ చేశారు."),
        "dua_condolence" to DuaText("సంతాపం (తాజియా)", "నిశ్చయంగా ఆయన తీసుకున్నది అల్లాహ్కే చెందుతుంది, ఆయన ఇచ్చినది కూడా ఆయనే. ఆయన వద్ద ఉన్న ప్రతిదానికీ ఒక నిర్దిష్ట కాలపరిమితి ఉంటుంది, కాబట్టి మీరు ఓపికగా ఉండి, ప్రతిఫలాన్ని ఆశించండి.", "ఒకరి మరణం తరువాత ఒక కుటుంబానికి సంతాపం తెలియజేస్తున్నాను.", "ప్రవక్త సల్లల్లాహు అలైహి వసల్లం ఈ సందేశాన్ని తన కుమార్తెకు పంపారు."),
        "dua_placing_in_grave" to DuaText("చనిపోయినవారిని సమాధిలో ఉంచడం", "అల్లాహ్ పేరిట మరియు అల్లాహ్ యొక్క ప్రవక్త మార్గంలో.", "మరణించిన వ్యక్తిని సమాధిలోకి దించేటప్పుడు.", "ఖననం యొక్క సున్నహ్ దుఆ."),
        "dua_sneezing" to DuaText("తుమ్ము", "అన్ని ప్రశంసలు అల్లాహ్కు చెందుతాయి.-అల్లాహ్ మిమ్మల్ని కరుణించుగాక.-అల్లాహ్ మీకు మార్గనిర్దేశం చేసి, మీ వ్యవహారాలను సరిదిద్దుగాక.", "తుమ్ము వచ్చినప్పుడు వినేవాడు'యార్హముకల్లా'అని చెబుతారు, అప్పుడు తుమ్మువాడు సమాధానం ఇస్తాడు.", "ఇది మరొక ముస్లింపై ఒక ముస్లిం హక్కు."),
        "dua_toilet_enter" to DuaText("టాయిలెట్లోకి ప్రవేశం", "అల్లాహ్ పేరిట. ఓ అల్లాహ్, నేను అపవిత్రమైన పురుషుడు మరియు స్త్రీ జిన్నుల నుండి నీకు ఆశ్రయం కోరుతున్నాను.", "టాయిలెట్లోకి అడుగు పెట్టే ముందు ఎడమ పాదంతో అడుగు పెట్టండి.", "బిస్మిల్లా అనేది జిన్నుకు, వ్యక్తికి మధ్య తెర అవుతుంది."),
        "dua_toilet_exit" to DuaText("టాయిలెట్ వదిలి", "(ఓ అల్లాహ్) నేను నీ క్షమాపణ కోరుతున్నాను.", "కుడి పాదంతో టాయిలెట్ నుండి బయటకు అడుగుపెట్టినప్పుడు.", "ప్రవాది సల్లల్లాహు అలైహి వసల్లం టాయిలెట్ నుండి బయటకు వచ్చినప్పుడు ఈ విషయం చెప్పారు."),
        "dua_thanking" to DuaText("ఎవరికైనా కృతజ్ఞతలు", "అల్లాహ్ మీకు మంచి బహుమతిని ప్రసాదించుగాక.", "ఎవరైనా మీకు సహాయం చేసినప్పుడు.", "ఇలా చెప్పిన వారెవరైనా తన కృతజ్ఞతలు తెలిపారు."),
        "dua_love_for_allah" to DuaText("ఎవరైనా'ఐ లవ్ యు ఫర్ అల్లాహ్'అని చెప్పినప్పుడు", "మీరు నన్ను ఎవరి కోసం ప్రేమిస్తున్నారో, ఆయన (అల్లాహ్) మిమ్మల్ని ప్రేమించుగాక.", "ఎవరైనా'అల్లాహ్ కోసం నేను నిన్ను ప్రేమిస్తున్నాను'అని చెప్పినప్పుడు.", "అల్లాహ్ పట్ల ప్రేమకు సున్నహ్ సమాధానం ఇస్తుంది."),
        "dua_seeing_muslim_smile" to DuaText("నమస్కారం (సలాం)", "మీకు శాంతి, అల్లాహ్ యొక్క దయ మరియు ఆయన ఆశీర్వాదాలు కలుగుగాక.", "ఒక ముస్లింను కలిసినప్పుడు.", "పూర్తి సలాం అని చెప్పడం వల్ల ముప్పై మంచి పనులు సంపాదిస్తారు."),
        "dua_dressing" to DuaText("దుస్తులు ధరించడం", "నాకు ఈ దుస్తులు ధరించి, నా వైపు నుండి ఎటువంటి శక్తి లేదా శక్తి లేకుండా నాకు అందించిన అల్లాహ్ కోసం అన్ని ప్రశంసలు.", "దుస్తులు ధరించినప్పుడు.", "గత పాపాల క్షమాపణ గురించి శుభవార్త."),
    )
}
